   'Push^Supino Reto;4;6-8;150;Valida|Desenvolvimento com Barra;4;8-10;120;Valida|Supino Inclinado com Halteres;3;10-12;105;Valida|Elevação Lateral;4;12-15;60;Valida|Tríceps Testa;3;10-12;60;Valida|Tríceps Corda;3;12-15;60;Valida~Pull^Barra Fixa;4;até a falha;120;Valida|Remada Cavalinho;4;8-10;150;Valida|Puxada Aberta;3;10-12;90;Valida|Face Pull;3;15;60;Valida|Rosca Direta;3;10-12;60;Valida|Rosca Martelo;3;12-15;60;Valida~Legs^Agachamento Livre;4;6-8;180;Valida|Levantamento Terra Romeno;4;8-10;150;Valida|Leg Press;3;12-15;120;Valida|Mesa Flexora;3;12-15;75;Valida|Panturrilha em Pé;4;12-15;60;Valida~Upper — leve^Supino Inclinado;3;10-12;90;Valida|Remada Máquina;3;10-12;90;Valida|Desenvolvimento Máquina;3;12-15;75;Valida|Crucifixo Inverso;3;15;60;Valida|Rosca na Polia;3;12-15;60;Valida|Tríceps Barra na Polia;3;12-15;60;Valida~Lower — leve^Agachamento Búlgaro;3;12 cada perna;105;Valida|Cadeira Extensora;3;15;75;Valida|Cadeira Flexora;3;15;75;Valida|Elevação Pélvica com Barra;3;12-15;90;Valida|Panturrilha Sentado;4;15-20;60;Valida|Prancha;3;45 seg;60;Valida'),
  ('Arnold Split — peito/costas, ombro/braços, pernas (6x por semana)','Hipertrofia','Avançado','A divisão clássica do fisiculturismo dos anos 70, rodando duas vezes na semana. Volume alto e sessões de peito com costas no mesmo dia, que é o que dá o efeito de "abrir" o tronco. Só para quem já treina há anos e dorme bem.',
   'A — Peito e costas^Supino Reto;2;10 leve;90;Aquecimento|Supino Reto;4;8-10;120;Valida|Barra Fixa;4;até a falha;120;Valida|Supino Inclinado com Halteres;4;8-10;105;Valida|Remada Curvada;4;8-10;105;Valida|Crucifixo;3;12-15;60;Valida|Pullover;3;12-15;60;Valida|Remada Baixa;3;10-12;75;Valida~B — Ombro e braços^Desenvolvimento com Halteres;2;12 leve;60;Aquecimento|Desenvolvimento com Barra;4;8-10;120;Valida|Elevação Lateral;4;12-15;60;Valida|Crucifixo Inverso;4;12-15;60;Valida|Rosca Direta;4;8-10;75;Valida|Tríceps Testa;4;8-10;75;Valida|Rosca Scott;3;12-15;60;Valida|Tríceps Corda;3;12-15;60;Valida~C — Pernas^Agachamento Livre;2;10 leve;90;Aquecimento|Agachamento Livre;5;6-8;180;Valida|Leg Press;4;10-12;150;Valida|Levantamento Terra Romeno;4;8-10;150;Valida|Cadeira Extensora;3;15;75;Valida|Mesa Flexora;3;12-15;75;Valida|Panturrilha em Pé;5;15;60;Valida|Abdominal na Polia;4;12-15;60;Valida')
),
divs as (
  select d.nome, d.objetivo, d.nivel, d.resumo,
         dv.txt as divtxt, dv.i - 1 as ordem_div
  from dados d,
       unnest(string_to_array(d.corpo, '~')) with ordinality as dv(txt, i)
),
exs as (
  select v.*, ex.txt as extxt, ex.i - 1 as ordem_ex
  from divs v,
       unnest(string_to_array(split_part(v.divtxt, '^', 2), '|')) with ordinality as ex(txt, i)
),
por_divisao as (
  select nome, objetivo, nivel, resumo, ordem_div,
         split_part(divtxt, '^', 1) as div_nome,
         jsonb_agg(jsonb_build_object(
           'nome',              split_part(extxt, ';', 1),
           'qtd_series',        split_part(extxt, ';', 2)::int,
           'faixa_reps',        split_part(extxt, ';', 3),
           'intervalo_seg_min', split_part(extxt, ';', 4)::int,
           'tipo_serie',        split_part(extxt, ';', 5),
           'ordem',             ordem_ex
         ) order by ordem_ex) as exercicios
  from exs
  group by nome, objetivo, nivel, resumo, ordem_div, divtxt
),
pronta as (
  select nome, objetivo, nivel, resumo,
         count(*)::int as dias,
         jsonb_agg(jsonb_build_object(
           'nome', div_nome, 'ordem', ordem_div, 'exercicios', exercicios
         ) order by ordem_div) as divisoes
  from por_divisao
  group by nome, objetivo, nivel, resumo
)
insert into public.train_ficha_modelo (coach_id, nome, objetivo, nivel, dias, resumo, divisoes)
select null, p.nome, p.objetivo, p.nivel, p.dias, p.resumo, p.divisoes
from pronta p
where not exists (
  select 1 from public.train_ficha_modelo m
  where m.nome = p.nome and m.coach_id is null
);
